use super::*;

// Captured from parent bd9a8c2 before extraction, never generated by these adapters.
const PARENT_SAVE: &[u8] = include_bytes!("../../../fixtures/save-schema23-new-run.json");

#[test]
fn schema23_source_restores_to_version24_without_fixture_state_loss() {
    let mut expected: serde_json::Value = serde_json::from_slice(PARENT_SAVE).unwrap();
    expected["schema_version"] = salimon_persistence::SCHEMA_VERSION.into();
    let current = GameplaySession::new_run().save_bytes(100).unwrap();
    assert_eq!(
        serde_json::from_slice::<serde_json::Value>(&current).unwrap(),
        expected
    );
    let mut restored = GameplaySession::default();
    restored.restore_bytes(PARENT_SAVE).unwrap();
    assert_eq!(restored.save_bytes(100).unwrap(), current);
}

#[test]
fn unknown_domain_fields_and_late_restore_failure_never_publish_partial_state() {
    let mut live = GameplaySession::new_run();
    live.advance_game(std::time::Duration::from_millis(16));
    let before = live.save_bytes(101).unwrap();
    let original: serde_json::Value = serde_json::from_slice(PARENT_SAVE).unwrap();
    for owner in [
        "physical",
        "offline",
        "surface_age",
        "finishes",
        "lighting",
        "core_upgrades",
        "mounts",
        "cargo_door",
        "habitation",
        "archive",
        "recovery",
        "construction",
        "fabrication",
        "equipment",
        "tutorial",
        "survival",
    ] {
        let mut corrupt = original.clone();
        corrupt["state"][owner]["unrecognized_future_field"] = true.into();
        assert!(
            live.restore_bytes(&serde_json::to_vec(&corrupt).unwrap())
                .is_err(),
            "{owner}"
        );
        assert_eq!(live.save_bytes(101).unwrap(), before, "{owner}");
    }
    let mut corrupt = original;
    // A valid mount ID references a fragment absent from the restored world.
    // DTO validation succeeds; cross-owner reconstruction must reject atomically.
    corrupt["state"]["mounts"]["mounts"][0]["secured"] = 999999.into();
    let bytes = serde_json::to_vec(&corrupt).unwrap();
    salimon_persistence::SaveGame::<SessionState>::decode(&bytes).unwrap();
    assert!(live.restore_bytes(&bytes).is_err());
    assert_eq!(live.save_bytes(101).unwrap(), before);
}
